//! On-device SF Symbol rasterization → `data:image/png;base64` data URLs,
//! via AppKit only (objc2-app-kit). In-memory cache; no assets are bundled.
//!
//! The popover paints these through a mask (`ui/src/components/Symbol.tsx`
//! invokes `symbol({ name, pt, weight })`); the glyph bytes are generated by
//! the OS, so the bundle never ships icon art for UI chrome.

use std::collections::HashMap;
use std::sync::{LazyLock, Mutex};

use objc2::MainThreadMarker;
use objc2_app_kit::{
    NSBitmapImageFileType, NSBitmapImageRep, NSFontWeightMedium, NSFontWeightRegular,
    NSFontWeightSemibold, NSImage, NSImageSymbolConfiguration, NSImageSymbolScale,
};
use objc2_foundation::{NSDataBase64EncodingOptions, NSDictionary, NSString};

static CACHE: LazyLock<Mutex<HashMap<String, String>>> =
    LazyLock::new(|| Mutex::new(HashMap::new()));
const MAX_CACHE_ENTRIES: usize = 256;

/// SF Symbol names are lowercase alphanumerics with dots (e.g. `bolt.fill`).
/// Anything else is rejected before it reaches AppKit.
pub fn is_valid_symbol_name(name: &str) -> bool {
    !name.is_empty()
        && name.len() <= 64
        && !name.starts_with('.')
        && !name.ends_with('.')
        && !name.contains("..")
        && name
            .chars()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '.' || c == '-')
}

/// `regular | medium | semibold` → NSFontWeight value.
pub fn weight_value(weight: &str) -> Result<f64, String> {
    // NSFontWeight* constants are extern statics; reading them is unsafe.
    match weight {
        "regular" => unsafe { Ok(NSFontWeightRegular) },
        "medium" => unsafe { Ok(NSFontWeightMedium) },
        "semibold" => unsafe { Ok(NSFontWeightSemibold) },
        other => Err(format!(
            "unknown weight {other:?} (expected regular|medium|semibold)"
        )),
    }
}

/// Rasterize an SF Symbol to a data URL.
/// `pt` is the UI point size (clamped to 8–64); the raster is rendered at 2×
/// for a crisp mask on retina displays. Requires the main thread (AppKit).
pub fn rasterize_symbol(name: &str, pt: f64, weight: &str) -> Result<String, String> {
    if !is_valid_symbol_name(name) {
        return Err(format!("invalid SF Symbol name {name:?}"));
    }
    let pt = pt.clamp(8.0, 64.0);
    let weight_value = weight_value(weight)?;
    let key = format!("{name}|{pt}|{weight}");
    {
        let cache = CACHE.lock().unwrap_or_else(|e| e.into_inner());
        if let Some(hit) = cache.get(&key) {
            return Ok(hit.clone());
        }
    }

    let _mtm = MainThreadMarker::new().ok_or("symbol rasterization requires the main thread")?;
    let ns_name = NSString::from_str(name);
    let image = NSImage::imageWithSystemSymbolName_accessibilityDescription(&ns_name, None)
        .ok_or_else(|| format!("unknown SF Symbol {name:?}"))?;
    let config = NSImageSymbolConfiguration::configurationWithPointSize_weight_scale(
        pt * 2.0, // 2× raster for a crisp mask
        weight_value,
        NSImageSymbolScale::Large,
    );
    let image = image.imageWithSymbolConfiguration(&config).unwrap_or(image);

    let tiff = image
        .TIFFRepresentation()
        .ok_or("TIFF representation failed")?;
    let rep = NSBitmapImageRep::imageRepWithData(&tiff).ok_or("bitmap representation failed")?;
    // Safety: the properties dictionary is empty; the type argument is PNG.
    let png = unsafe {
        rep.representationUsingType_properties(
            NSBitmapImageFileType::PNG,
            &NSDictionary::dictionary(),
        )
    }
    .ok_or("PNG encoding failed")?;
    let data_url = format!(
        "data:image/png;base64,{}",
        png.base64EncodedStringWithOptions(NSDataBase64EncodingOptions(0))
    );

    let mut cache = CACHE.lock().unwrap_or_else(|e| e.into_inner());
    if cache.len() >= MAX_CACHE_ENTRIES {
        cache.clear();
    }
    cache.insert(key, data_url.clone());
    Ok(data_url)
}
